using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using HimoHitoA2Proof;
using UnityEngine;

namespace HimoHito
{
    // Explicit diagnostic only. Original movement field/API; never OS/Human input.
    [DefaultExecutionOrder(20000)]public sealed class WallCollisionReview:MonoBehaviour
    {
        public static WallCollisionReview Instance;
        public A2Fixture f;A2InputDriver input;WallContactMonitor monitor;
        [Serializable]public class State
        {
            public float t,fixedTime,remaining,ropeLength,span,input,angle,soleY;
            public int selected,bridges;public bool attached,grounded,failure;
            public Vector2 position,velocity,colliderMin,colliderMax,crown;
            public Vector3 camera;public float ortho;
        }
        [Serializable]public class Contact
        {
            public string collider,face,callback;public int step;
            public Vector2 point,normal,relativeVelocity;public float normalImpulse,tangentImpulse;
            public State before,afterMover,after;
        }
        [Serializable]public class Step{public int step;public State before,afterMover,after;}
        [Serializable]public class Trial
        {
            public string name,policy;public int length;public float releaseAt,attachTime=-1,releaseTime=-1;
            public bool attachAccepted,landed,finished,entryValid;public State end;
            public State beforeRetry,immediateRetry,settledRetry;public bool retryPassed;
            public List<State> entryAttempts=new List<State>();
            public List<Contact> contacts=new List<Contact>();public List<Step> steps=new List<Step>();
        }
        [Serializable]public class Result
        {
            public string method="Explicit automatic original input-field/API and Unity Physics2D. NOT OS keys/Human.",layout,mode;
            public bool finished;public int errors;public List<Trial> trials=new List<Trial>();
        }
        public Trial active;public float started;public bool measuring;int frame;
        Result result=new Result();bool filming;string movieFolder;
        IEnumerator Start()
        {
            Instance=this;
            while(!(f=A2Fixture.Instance)||!f.Ready||!f.Body.GetComponent<PlayerMotionPresentation>())yield return null;
            while(Time.time<1)yield return null;
            input=f.gameObject.AddComponent<A2InputDriver>();monitor=f.Body.gameObject.AddComponent<WallContactMonitor>();
            monitor.owner=this;f.Body.gameObject.AddComponent<WallAfterMover>().monitor=monitor;
            result.layout=A2Fixture.Arg("-wallLayout","bevel");result.mode=A2Fixture.Arg("-wallMode","diagnosis");
            f.Write("WallConfig.json",new A2Fixture.Config(f));
            var solids=new List<A2Fixture.Shape>();
            foreach(var c in FindObjectsByType<Collider2D>(FindObjectsSortMode.None))if(c.enabled&&!c.isTrigger)solids.Add(new A2Fixture.Shape(c.gameObject));
            f.Write("SolidColliders.json",new Solids{colliders=solids});
            if(result.mode=="diagnosis")
            {
                foreach(int length in new[]{6,7})
                {
                    yield return Run(length,"ground_follow",-1,5);
                    yield return Run(length,"ground_right",-1,4);
                    yield return Run(length,"ground_right",.65f,4);
                    yield return Run(length,"ground_right",1.05f,4);
                }
            }
            else if(result.mode=="compare")
            {
                int length=(int)A2Fixture.Number("-wallLength",6);
                string policy=A2Fixture.Arg("-wallPolicy","jump_follow");
                float release=A2Fixture.Number("-wallRelease",-1);
                filming=A2Fixture.Arg("-wallFilm","0")=="1";
                yield return Run(length,policy,release,A2Fixture.Number("-wallDuration",5));
            }
            else if(result.mode=="matrix")
            {
                foreach(int length in new[]{6,7})
                {
                    yield return Run(length,"ground_follow",-1,5);
                    yield return Run(length,"ground_timed",-1,5);
                    yield return Run(length,"ground_coast",-1,5);
                    foreach(float angle in new[]{24f,30f,42f,54f})yield return Run(length,"ground_angle",angle,5);
                }
            }
            result.finished=true;result.errors=f.Errors;File.WriteAllText(Path.Combine(f.Output,"WallResult.json"),JsonUtility.ToJson(result,false));
            yield return new WaitForSeconds(.1f);A2Fixture.Quit(f.Errors==0?0:2);
        }
        IEnumerator Run(int length,string policy,float release,float duration)
        {
            input.Move=0;input.Jump=false;f.ResetTrial();yield return new WaitForSeconds(1.7f);
            active=new Trial{name="L"+length+"_"+policy+"_release"+release,policy=policy,length=length,releaseAt=release};
            active.entryAttempts.Add(Observe());
            if(!ValidEntry()){f.Retry();yield return new WaitForSeconds(1.7f);active.entryAttempts.Add(Observe());}
            active.entryValid=ValidEntry();result.trials.Add(active);
            if(!active.entryValid){active.finished=true;active.end=Observe();yield break;}
            f.Rope.RestoreSelectedRopeLength(length);
            started=Time.fixedTime;frame=0;monitor.ResetCounter();measuring=true;
            if(filming){movieFolder=Path.Combine(f.Output,"Frames");Directory.CreateDirectory(movieFolder);StartCoroutine(Frames());}
            if(policy.StartsWith("jump"))
            {
                input.Jump=true;input.Move=1;
                yield return new WaitForSeconds(.4f);
            }
            active.attachAccepted=f.Rope.TryAttach(GameObject.Find(A2Fixture.SwingNames[0]).transform.position);
            active.attachTime=Time.fixedTime-started;input.Move=1;
            float end=started+duration;
            while(Time.fixedTime<end)
            {
                float t=Time.fixedTime-started;
                Vector2 d=f.Body.position-f.Rope.AnchorPoint;
                bool releaseNow=policy.EndsWith("angle")?
                    Mathf.Atan2(d.x,-d.y)*Mathf.Rad2Deg>=release&&f.Body.linearVelocity.x>0&&f.Body.linearVelocity.y>0:
                    t-active.attachTime>=release;
                if(release>=0&&active.releaseTime<0&&releaseNow&&f.Rope.IsAttached)
                {f.Rope.DetachAndRefund(true);active.releaseTime=t;}
                if(policy.EndsWith("timed"))
                    input.Move=t-active.attachTime<1.7f?1:t-active.attachTime<3.4f?-1:1;
                else if(policy.EndsWith("follow")&&f.Rope.IsAttached)
                    input.Move=Mathf.Abs(f.Body.linearVelocity.x)>.1f?Mathf.Sign(f.Body.linearVelocity.x):input.Move;
                else if(policy.EndsWith("coast")&&t-active.attachTime>1)input.Move=0;
                else input.Move=1;
                // Fixed-duration movies keep the same input schedule after a landing/failure.
                if(f.OnBank(f.Middle)&&!f.Rope.IsAttached)active.landed=true;
                yield return new WaitForFixedUpdate();
            }
            if(Application.isBatchMode)yield return null;else yield return new WaitForEndOfFrame();
            measuring=false;input.Move=0;active.end=Observe();active.finished=true;
            active.beforeRetry=Observe();f.Retry();active.immediateRetry=Observe();
            yield return new WaitForSeconds(1.1f);active.settledRetry=Observe();active.retryPassed=ValidEntry()&&f.Rope.SelectedRopeLength==6;
            Debug.Log("WALL_TRIAL "+active.name+" attach="+active.attachAccepted+" landed="+active.landed+" contacts="+active.contacts.Count);
            f.Write("WallProgress.json",new Progress{name=active.name,completed=result.trials.Count,contacts=active.contacts.Count,retryPassed=active.retryPassed});
        }
        bool ValidEntry()=>f.Body.simulated&&f.Mover.IsGrounded&&!f.Rope.IsAttached&&!f.Respawn.IsFailureVisible&&Vector2.Distance(f.Body.position,f.Spawn)<.2f&&f.Resource.CurrentLength==24&&f.Builder.GeneratedPlatformCount==0;
        public State Observe()
        {
            var c=f.Body.GetComponent<Collider2D>();var art=f.Body.GetComponent<RopeBodyVisual>();
            var renderers=new List<SpriteRenderer>();art.CollectCharacterRenderers(renderers);float sole=float.PositiveInfinity;
            foreach(var r in renderers)if(r&&r.enabled&&r.sprite)sole=Mathf.Min(sole,PlayerSoleRegistration.WorldPoint(r).y);
            Vector2 delta=f.Body.position-f.Rope.AnchorPoint;
            return new State{t=Time.fixedTime-started,fixedTime=Time.fixedTime,position=f.Body.position,velocity=f.Body.linearVelocity,
                colliderMin=c.bounds.min,colliderMax=c.bounds.max,crown=art.RopeOrigin,soleY=float.IsInfinity(sole)?0:sole,
                attached=f.Rope.IsAttached,grounded=f.Mover.IsGrounded,failure=f.Respawn.IsFailureVisible,
                input=input?input.Move:0,selected=f.Rope.SelectedRopeLength,ropeLength=f.Rope.ActiveRopeLength,
                span=delta.magnitude,angle=Mathf.Atan2(delta.x,-delta.y)*Mathf.Rad2Deg,
                remaining=f.Resource.CurrentLength,bridges=f.Builder.GeneratedPlatformCount,
                camera=Camera.main.transform.position,ortho=Camera.main.orthographicSize};
        }
        void LateUpdate(){if(monitor)monitor.AfterPhysics();}
        IEnumerator Frames()
        {
            while(measuring)
            {
                yield return new WaitForEndOfFrame();if(!measuring)break;
                var image=ScreenCapture.CaptureScreenshotAsTexture();
                File.WriteAllBytes(Path.Combine(movieFolder,"Frame_"+frame.ToString("D4")+".jpg"),image.EncodeToJPG(78));Destroy(image);frame++;
            }
        }
        [Serializable]public class Solids{public List<A2Fixture.Shape> colliders;}
        [Serializable]public class Progress{public string name;public int completed,contacts;public bool retryPassed;}
    }
    [DefaultExecutionOrder(-30000)]public sealed class WallContactMonitor:MonoBehaviour
    {
        public WallCollisionReview owner;public int counter;WallCollisionReview.Step step;
        public void ResetCounter(){counter=0;step=null;}
        void FixedUpdate()
        {
            if(!owner||!owner.measuring)return;
            step=new WallCollisionReview.Step{step=counter++,before=owner.Observe()};owner.active.steps.Add(step);
        }
        public void AfterMover(){if(owner&&owner.measuring&&step!=null)step.afterMover=owner.Observe();}
        public void AfterPhysics(){if(owner&&owner.measuring&&step!=null)step.after=owner.Observe();}
        void OnCollisionEnter2D(Collision2D c)=>Contact(c,"enter");
        void OnCollisionStay2D(Collision2D c)=>Contact(c,"stay");
        void Contact(Collision2D c,string kind)
        {
            if(!owner||!owner.measuring||step==null)return;
            Collider2D other=c.collider==GetComponent<Collider2D>()?c.otherCollider:c.collider;
            foreach(var p in c.contacts)
                owner.active.contacts.Add(new WallCollisionReview.Contact{collider=other.name,face=other.name=="A2 Proof Entry Bevel"?"slope":Mathf.Abs(p.normal.x)>.65f?"side":p.normal.y<-.65f?"underside":"top_or_corner",callback=kind,step=step.step,point=p.point,normal=p.normal,relativeVelocity=c.relativeVelocity,normalImpulse=p.normalImpulse,tangentImpulse=p.tangentImpulse,before=step.before,afterMover=step.afterMover,after=owner.Observe()});
        }
    }
    [DefaultExecutionOrder(5000)]public sealed class WallAfterMover:MonoBehaviour
    {public WallContactMonitor monitor;void FixedUpdate(){if(monitor)monitor.AfterMover();}}
}
